#!/usr/bin/env python3
# SPDX-License-Identifier: Apache-2.0
# Copyright 2025-2026 The LoopZero Authors
"""One-shot generator: parse env master table → write runtime-env-manifest.txt.

Reads `.claude/knowledge-base/audits/2026-06-18-env-master-table.md` from the
umbrella workspace (one level up from loopzero/), filters scope=runtime rows, and
writes `runtime-env-manifest.txt` in this directory in the canonical format
`VAR|plane|req|section`.

This is NOT a runtime test helper — it produces the checked-in fixture that
the hermetic Go guard `TestRuntimeEnvCompleteness` reads. Per D2 of plan
`dev-public-env-config-completeness`: the Go test stays hermetic (reads only
checked-in fixture, not the umbrella .md across repos). Regenerate by hand
when the master table changes; EC-5 sync floor in the Go test FAILs loud if
the regeneration is forgotten.

Usage:
    cd loopzero/infra/tests/fixtures
    python3 _generate_runtime_manifest.py

Output: writes runtime-env-manifest.txt (sorted, deterministic).
"""
import pathlib
import re
import sys

MASTER_TABLE_REL = "../../../../.claude/knowledge-base/audits/2026-06-18-env-master-table.md"
OUT_FILE = "runtime-env-manifest.txt"

# Section header regex — `## A. cloud-API ... chart \`loopzero-cloud\`` form.
SECTION_RE = re.compile(r"^## ([A-Z])\. .*chart[s]? `([^`]+)`")
# Sub-section `### B.1 SECRET — runtime (27)` form (used for B; not all letters
# have sub-sections; we fall back to top-level letter when sub-section absent).
SUBSECTION_RE = re.compile(r"^### ([A-Z]\.\d+) ")
# Data row: `| VAR | plane | scope | req | note |`. The leading `| ` and the
# UPPER_SNAKE name anchor the match so we skip header rows + the legend.
ROW_RE = re.compile(r"^\|\s+([A-Z][A-Z0-9_]*)\s+\|\s+(SECRET|CONFIG)\s+\|\s+(runtime|tooling|test|drill|infra|k8s)\s+\|\s+([^|]*?)\s+\|")


def main() -> int:
    fixtures_dir = pathlib.Path(__file__).resolve().parent
    master = fixtures_dir / MASTER_TABLE_REL
    master = master.resolve()
    if not master.exists():
        print(f"ERROR: master table not found at {master}", file=sys.stderr)
        return 1

    rows: list[tuple[str, str, str, str]] = []
    current_section = ""
    with master.open() as f:
        for line in f:
            m = SECTION_RE.match(line)
            if m:
                current_section = m.group(2)  # chart name from header (loopzero-cloud / loopzero-api / ...)
                continue
            r = ROW_RE.match(line)
            if not r:
                continue
            var = r.group(1)
            plane = r.group(2)
            scope = r.group(3)
            req = r.group(4).strip()
            if scope != "runtime":
                continue
            rows.append((var, plane, req, current_section))

    if not rows:
        print("ERROR: parsed zero runtime rows — parser regex broken", file=sys.stderr)
        return 2

    # Dedup by (var, section) — same var consumed by multiple components
    # appears once per section (chart), which is what the install-config-contract
    # checks. Keep all (var,section) pairs; sort deterministic.
    seen: set[tuple[str, str]] = set()
    unique: list[tuple[str, str, str, str]] = []
    for var, plane, req, section in rows:
        key = (var, section)
        if key in seen:
            continue
        seen.add(key)
        unique.append((var, plane, req, section))
    unique.sort()

    out = fixtures_dir / OUT_FILE
    with out.open("w") as f:
        f.write("# runtime-env-manifest.txt — GENERATED by _generate_runtime_manifest.py\n")
        f.write("# DO NOT EDIT BY HAND. Regenerate when master table changes.\n")
        f.write("# Source: .claude/knowledge-base/audits/2026-06-18-env-master-table.md (umbrella)\n")
        f.write("# Format: VAR|plane|req|chart-section\n")
        f.write(f"# Row count: {len(unique)}\n")
        f.write("#\n")
        for var, plane, req, section in unique:
            f.write(f"{var}|{plane}|{req}|{section}\n")

    print(f"wrote {len(unique)} rows to {out}", file=sys.stderr)
    return 0


if __name__ == "__main__":
    sys.exit(main())
